def solve(inputs: dict) -> float:
    # Parse TERMS as a list
    import json

    # Handle if TERMS is passed as a list or JSON string
    terms = inputs['TERMS']
    if isinstance(terms, str):
        terms = json.loads(terms)

    # For continued fractions, we need two initial conditions:
    # p_{-1} = 1, p_0 = a_0
    # Then p_n = a_n * p_{n-1} + p_{n-2}

    if len(terms) == 0:
        return 0.0

    p_prev2 = 1  # p_{-1}
    p_prev1 = terms[0]  # p_0 = a_0

    # If there's only one term, return it
    if len(terms) == 1:
        return float(p_prev1)

    # Apply recurrence for remaining terms
    for i in range(1, len(terms)):
        p_curr = terms[i] * p_prev1 + p_prev2
        p_prev2 = p_prev1
        p_prev1 = p_curr

    return float(p_prev1)

